  function paidMinutesFor(c){const before=c.original_data?.shift||c.original_data||{},after=c.proposed_data||{},start=new Date(after.proposedAt&&['missing_in','wrong_in'].includes(c.correction_type)?after.proposedAt:before.startedAt),end=new Date(after.proposedAt&&['missing_out','wrong_out'].includes(c.correction_type)?after.proposedAt:before.endedAt);return Number.isFinite(end-start)?Math.max(0,Math.round((end-start)/60000)-Number(before.autoBreakMinutes||0)):null;}
  function correctionCard(c){const status=requestStatus[c.status]||c.status,minutes=paidMinutesFor(c);return `<article class="punch-request-card"><button class="punch-request-open" data-correction-open="${esc(c.id)}"><span><strong>${esc(c.employeeName||state.members.find(m=>m.id===c.employee_id)?.name||'Employé')}</strong><small>${esc(c.workDate||'Journée à confirmer')} · ${esc(correctionLabels[c.correction_type]||c.correction_type)}</small></span>${StatusBadge(status,c.status==='refused'?'danger':c.status==='pending'||c.status==='clarification'?'warn':'')}</button><p>${esc(c.explanation||'Aucune explication')}</p><footer><span>${minutes===null?'Incidence à calculer':`${num(minutes/60)} h payées proposées`}</span>${c.attachment_path?'<span>📎 Pièce jointe</span>':''}</footer></article>`;}
