    if(view==='management-invoices')return `<section class="management-page">${heading('FINANCES','Facturation et comptes à recevoir','Les soldes et les prochaines actions, en mots simples.')}<div class="mg-list mg-list-page">${(data.invoices||[]).map(i=>`<article><div><strong>${esc(i.number)} · ${esc(i.client)}</strong><span>${money(i.total)} · payé ${money(i.paid)} · échéance ${esc(i.dueDate)}</span></div>${StatusBadge(invoiceLabel(i.status),i.status==='overdue'?'danger':'')}${!['paid','cancelled','credited'].includes(i.status)?`<button data-payment="${esc(i.id)}">Inscrire un paiement</button>`:''}</article>`).join('')||EmptyState('Aucune facture','Créez une facture à partir d’un contrat ou d’un chantier.')}</div></section>`;
