  function jobNumber(job){const explicit=String(job?.number||job?.jobNumber||'').trim();if(explicit)return explicit;const name=String(job?.name||''),match=name.match(/(?:^\s*|\b(?:job|chantier)\s*#?\s*-?)(\d{2,})\b/i);return match?.[1]||'—';}
