  function renderMessages(){const messaging=state.messaging||{},contacts=messaging.contacts||[],teams=messaging.teams||[],conversations=messaging.conversations||[],selected=conversations.find(item=>item.id===ui.conversationId),contactMap=new Map(contacts.map(item=>[item.id,item])),online=navigator.onLine!==false;
    const list=`<aside class="chat-list-pane"><div class="chat-list-head">${heading('MESSAGES','Conversations','Privées, équipe et chantier.')}<form id="chat-search-form" role="search"><label><span class="sr-only">Rechercher dans les messages</span>${icon('search')}<input name="query" type="search" maxlength="120" value="${esc(chatQuery)}" placeholder="Rechercher"></label><button class="button secondary" type="submit">Chercher</button></form></div>${chatSearchResults?`<div class="chat-search-results"><div class="chat-section-title"><strong>Résultats</strong><button type="button" data-chat-search-close>Fermer</button></div>${chatSearchResults.length?chatSearchResults.map(message=>`<button type="button" data-conversation="${esc(message.conversationId)}"><strong>${esc(message.body||'Pièce jointe')}</strong><small>${date(message.sentAt)}</small></button>`).join(''):chatState('empty','Aucun résultat','Essayez un autre mot.')}</div>`:`<div class="chat-start"><details><summary>Nouvelle conversation</summary>${contacts.map(person=>`<button type="button" data-start-private="${esc(person.id)}"><strong>${esc(person.name)}</strong><small>Conversation privée · ${esc(person.role)}</small></button>`).join('')}${teams.map(team=>`<button type="button" data-start-team="${esc(team.id)}"><strong>${esc(team.name)}</strong><small>Conversation d’équipe</small></button>`).join('')}</details></div><div class="chat-conversations">${conversations.length?conversations.map(conversation=>{const label=chatConversationLabel(conversation,teams,contactMap),kind=conversation.kind==='job'?'Chantier':conversation.kind==='team'?'Équipe':'Privé';return `<button type="button" data-conversation="${esc(conversation.id)}" aria-current="${conversation.id===ui.conversationId?'true':'false'}"><span class="chat-avatar">${esc(kind.slice(0,2).toUpperCase())}</span><span><strong>${esc(label)}</strong><small>${esc(kind)}${conversation.lastMessage?.body?' · '+esc(conversation.lastMessage.body):''}</small></span>${conversation.unread?`<b class="chat-unread">${Number(conversation.unread)}</b>`:'<time>À jour</time>'}</button>`;}).join(''):chatState('empty','Aucune conversation','Les conversations autorisées apparaîtront ici.')} ${messaging.conversationPage?.hasMore?'<button type="button" class="button secondary chat-more" data-chat-conversations-more>Conversations suivantes</button>':''}</div>`}</aside>`;
    if(!selected)return `<section class="chat-workspace">${list}<div class="chat-placeholder">${online?chatState('empty','Choisissez une conversation','Les messages et pièces jointes s’ouvriront ici.'):chatState('offline','Vous êtes hors ligne','Les conversations déjà affichées restent visibles.')}</div></section>`;
    const messages=(messaging.messages||[]).filter(item=>item.conversationId===selected.id),title=chatConversationLabel(selected,teams,contactMap),draft=chatDraft(selected.id);
    const thread=`<section class="message-thread"><header class="chat-thread-head"><button type="button" class="button quiet chat-back" data-messages-back>← Conversations</button><div><p class="portal-eyebrow">${selected.kind==='job'?'CHANTIER':selected.kind==='team'?'ÉQUIPE':'PRIVÉ'}</p><h1>${esc(title)}</h1></div></header>${!online?'<div class="chat-network" role="status">Hors ligne · le brouillon texte reste sur cet appareil. Une pièce jointe non téléchargée ne peut pas être ouverte.</div>':''}${chatError?chatState('error','Accès impossible',chatError,'<button type="button" data-chat-retry>Réessayer</button>'):''}<div class="message-list" aria-busy="${chatLoading}">${messaging.messagePages?.[selected.id]?.hasMore?'<button type="button" class="button secondary chat-more" data-chat-messages-more>Messages précédents</button>':''}${chatLoading&&!messages.length?chatState('loading','Chargement des messages','Un instant…'):messages.length?messages.map(message=>`<article class="${message.senderId===actorId?'mine':'theirs'}"><p>${esc(message.body)}</p>${message.jobId?`<button type="button" data-job="${esc(message.jobId)}">Ouvrir le job</button>`:''}${chatAttachment(message)}<small>${date(message.sentAt)}${message.senderId===actorId?` · ${message.readCount?`Lu par ${message.readCount} sur ${message.recipientCount}`:message.deliveredCount?'Distribué':'Envoyé'}`:''}</small></article>`).join(''):chatState('empty','Aucun message','Écrivez le premier message de cette conversation.')}</div>${selected.readOnly?chatState('denied','Chantier archivé · lecture seule.','Les nouveaux envois sont refusés.'):`<form id="message-form" data-conversation="${esc(selected.id)}"><div class="chat-draft-status">${draft?'Brouillon enregistré':'Écrivez un message ou joignez une photo ou un PDF'}</div><label class="chat-compose"><span class="chat-file-button" title="Joindre une photo ou un PDF">＋<input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,application/pdf" aria-label="Joindre une photo ou un PDF"></span><textarea name="body" maxlength="4000" rows="1" placeholder="Écrire un message…" aria-label="Message">${esc(draft)}</textarea><button class="button chat-send" type="submit"${chatBusy||!online?' disabled':''}>${chatBusy?'Envoi…':'Envoyer'}</button></label><small class="chat-document-limit">Photos et PDF · 10 Mo maximum · passerelle privée. Le texte du brouillon est conservé; le fichier sélectionné doit être choisi de nouveau après rechargement.</small></form>`}</section>`;
    return `<section class="chat-workspace has-thread">${list}${thread}</section>`;}
  function renderAccount(){const requests=state.operations?.hrRequests||[];return `<section class="employee-simple">${heading('MON COMPTE','Congés, absences et heures','Vos renseignements RH restent séparés des chantiers et des messages.')}<div class="account-action-list"><button type="button" data-view="expenses">Mes dépenses et reçus ${icon('arrow')}</button>${state.punch?.enabled?`<button type="button" data-view="punch-hours">Mes heures ${icon('arrow')}</button>`:''}<button type="button" data-hr="absence">Signaler une absence aujourd’hui ${icon('arrow')}</button><button type="button" data-hr="leave">Demander un congé ou des vacances ${icon('arrow')}</button><button type="button" data-hr="requests">Mes demandes ${icon('arrow')}</button></div>${requests.length?`<div class="hr-request-list"><h2>Mes demandes</h2>${requests.filter(item=>item.employeeId===actorId).map(item=>`<article><strong>${item.type==='vacation'?'Vacances':item.type==='leave'?'Congé':'Absence'}</strong><span>${esc(item.startDate)} → ${esc(item.endDate)}</span><b>${item.status==='approved'?'Approuvé':item.status==='refused'?'Refusé':'En attente'}</b></article>`).join('')}</div>`:''}</section>`;}
  
