    const element=event.target;
    if(element.dataset.ruleRequirement){const rule=logistics().rules.find(r=>r.id===element.dataset.ruleRequirement);if(!rule)return;portalClient.adminLogisticsAction('rule_save',rule.id,{phase:rule.phase,code:rule.code,label:rule.label,requirement:element.value,vehicleType:rule.vehicle_type||'',vehicleId:rule.vehicle_id||'',trailerOnly:!!rule.trailer_only,position:rule.position,photoRequired:!!rule.photo_required,commentRequired:!!rule.comment_required,failureBlocks:!!rule.failure_blocks,approverRole:rule.approver_role||'boss_admin'}).then(()=>toast('Paramètre enregistré.')).catch(error=>toast(errorMessage(error)));return;}
